CREATE TABLE portfolio_assets (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), portfolio_id UUID NOT NULL REFERENCES portfolios(id) ON DELETE CASCADE, project_id UUID REFERENCES projects(id) ON DELETE CASCADE, asset_type VARCHAR(30) NOT NULL, object_key VARCHAR(500) NOT NULL UNIQUE, original_filename VARCHAR(255), content_type VARCHAR(100), file_size BIGINT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_portfolio_assets_portfolio_id ON portfolio_assets(portfolio_id); CREATE INDEX idx_portfolio_assets_project_id ON portfolio_assets(project_id); CREATE INDEX idx_portfolio_assets_type ON portfolio_assets(asset_type);
